#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');

const storage = path.join(process.cwd(), 'names.json');

function readNames() {
  let text;
  try {
    text = fs.readFileSync(storage, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
  const names = JSON.parse(text);
  if (!Array.isArray(names) || !names.every((name) => typeof name === 'string')) {
    throw new Error('names.json 必须是名字字符串数组');
  }
  return names;
}

try {
  const [command, ...args] = process.argv.slice(2);
  if (command === 'add') {
    if (args.length !== 1 || args[0].trim() === '') {
      throw new Error('用法：name-list add "名字"（需要一个非空名字）');
    }
    const names = readNames();
    names.push(args[0]);
    fs.writeFileSync(storage, JSON.stringify(names, null, 2) + '\n', 'utf8');
  } else if (command === 'list' && args.length === 0) {
    const names = readNames();
    if (names.length > 0) process.stdout.write(names.join('\n') + '\n');
  } else {
    throw new Error('未知命令或参数；用法：name-list add "名字" | name-list list');
  }
} catch (error) {
  console.error(`name-list：${error.message}`);
  process.exitCode = 1;
}
